unsafe fn init_driver_lookaside(
    la: u64,
    allocate: u64,
    free: u64,
    size: u64,
    tag: u64,
    depth: u64,
    pool_type: u32,
) {
    if la == 0 {
        return;
    }
    let alloc_fn = if allocate != 0 {
        allocate
    } else {
        s_lookaside_alloc as *const () as usize as u64
    };
    let free_fn = if free != 0 {
        free
    } else {
        s_lookaside_free as *const () as usize as u64
    };
    nt_kernel_exec::init_general_lookaside(
        la as *mut u8,
        la,
        alloc_fn,
        free_fn,
        size as u32,
        tag as u32,
        depth as u16,
        pool_type,
    );
}

