unsafe fn write_key_value_partial_raw(
    value_type: u32,
    data_bytes: &[u8],
    key_value_information: u64,
    length: u32,
    result_length: u64,
) -> i32 {
    let need = 12usize.saturating_add(data_bytes.len());
    if result_length != 0 {
        write_unaligned(result_length as *mut u32, need as u32);
    }
    if need > u32::MAX as usize || key_value_information == 0 || length < need as u32 {
        return STATUS_BUFFER_TOO_SMALL;
    }
    write_unaligned(key_value_information as *mut u32, 0);
    write_unaligned((key_value_information + 4) as *mut u32, value_type);
    write_unaligned((key_value_information + 8) as *mut u32, data_bytes.len() as u32);
    let data = key_value_information + 12;
    let mut i = 0usize;
    while i < data_bytes.len() {
        write_unaligned((data + i as u64) as *mut u8, data_bytes[i]);
        i += 1;
    }
    STATUS_SUCCESS
}

unsafe fn write_key_basic_information(
    name_utf16: &[u8],
    key_information: u64,
    length: u32,
    result_length: u64,
) -> i32 {
    let need = 16usize.saturating_add(name_utf16.len());
    if result_length != 0 {
        write_unaligned(result_length as *mut u32, need as u32);
    }
    if need > u32::MAX as usize || key_information == 0 || length < need as u32 {
        return STATUS_BUFFER_TOO_SMALL;
    }
    write_unaligned(key_information as *mut u64, 0);
    write_unaligned((key_information + 8) as *mut u32, 0);
    write_unaligned((key_information + 12) as *mut u32, name_utf16.len() as u32);
    let name = key_information + 16;
    let mut i = 0usize;
    while i < name_utf16.len() {
        write_unaligned((name + i as u64) as *mut u8, name_utf16[i]);
        i += 1;
    }
    STATUS_SUCCESS
}

unsafe fn write_allocated_unicode_string_from_utf16le_data(us: u64, data: &[u8]) -> i32 {
    if us == 0 || (data.len() & 1) != 0 {
        return STATUS_INVALID_PARAMETER;
    }
    let mut string_len = data.len();
    if string_len >= 2 && data[string_len - 2] == 0 && data[string_len - 1] == 0 {
        string_len -= 2;
    }
    if string_len > u16::MAX as usize - 2 {
        return STATUS_INVALID_PARAMETER;
    }
    let alloc_len = string_len + 2;
    let buf = pool_alloc(alloc_len as u64);
    if buf == 0 {
        return STATUS_INSUFFICIENT_RESOURCES;
    }
    let mut i = 0usize;
    while i < string_len {
        write_unaligned((buf + i as u64) as *mut u8, data[i]);
        i += 1;
    }
    write_unaligned((buf + string_len as u64) as *mut u16, 0);
    write_unaligned(
        (us + UNICODE_STRING_LENGTH_OFFSET) as *mut u16,
        string_len as u16,
    );
    write_unaligned(
        (us + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
        alloc_len as u16,
    );
    write_unaligned((us + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, buf);
    STATUS_SUCCESS
}

unsafe fn write_rtl_direct_registry_value(value_type: u32, data: &[u8], entry_context: u64) -> i32 {
    if entry_context == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    match value_type {
        REG_SZ | REG_EXPAND_SZ | REG_MULTI_SZ => {
            write_allocated_unicode_string_from_utf16le_data(entry_context, data)
        }
        REG_DWORD if data.len() == 4 => {
            write_unaligned(
                entry_context as *mut u32,
                u32::from_le_bytes([data[0], data[1], data[2], data[3]]),
            );
            STATUS_SUCCESS
        }
        _ => STATUS_NOT_SUPPORTED,
    }
}

/// `NTSTATUS ZwOpenKey(PHANDLE, ACCESS_MASK, POBJECT_ATTRIBUTES)`.
extern "win64" fn s_zw_open_key(
    handle_out: u64,
    _desired_access: u32,
    object_attributes: u64,
) -> i32 {
    if handle_out != 0 {
        unsafe {
            write_unaligned(handle_out as *mut u64, 0);
        }
    }
    if handle_out == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let Some((root, name)) =
            object_attributes_root_and_name::<HOSTED_REGISTRY_PATH_MAX>(object_attributes)
        else {
            return STATUS_INVALID_PARAMETER;
        };
        if !write_registry_arg_ascii(
            HOSTED_REGISTRY_ARG_KEY_LEN,
            HOSTED_REGISTRY_ARG_KEY_OFF,
            &name,
        ) {
            return STATUS_INVALID_PARAMETER;
        }
        let (status, handle, _) =
            hosted_registry_broker_call(HOSTED_REGISTRY_OP_OPEN_RELATIVE_KEY, root, 0, 0);
        if status != STATUS_SUCCESS {
            return status;
        }
        write_unaligned(handle_out as *mut u64, handle);
    }
    STATUS_SUCCESS
}

/// `NTSTATUS ZwEnumerateKey(...)`.
extern "win64" fn s_zw_enumerate_key(
    handle: u64,
    index: u32,
    key_information_class: u32,
    key_information: u64,
    length: u32,
    result_length: u64,
) -> i32 {
    unsafe {
        if key_information_class != KEY_BASIC_INFORMATION_CLASS {
            if result_length != 0 {
                write_unaligned(result_length as *mut u32, 0);
            }
            return STATUS_NOT_SUPPORTED;
        }
        let (status, name_len, _) =
            hosted_registry_broker_call(HOSTED_REGISTRY_OP_ENUMERATE_KEY, handle, index as u64, 0);
        match status {
            STATUS_SUCCESS => write_key_basic_information(
                registry_arg_data_slice(name_len as u32),
                key_information,
                length,
                result_length,
            ),
            status => {
                if result_length != 0 {
                    write_unaligned(result_length as *mut u32, 0);
                }
                status
            }
        }
    }
}

/// `NTSTATUS ZwQueryValueKey(...)` against a hosted driver registry handle.
extern "win64" fn s_zw_query_value_key(
    handle: u64,
    value_name: u64,
    key_value_information_class: u32,
    key_value_information: u64,
    length: u32,
    result_length: u64,
) -> i32 {
    unsafe {
        let value_name =
            match unicode_string_to_hosted_ascii::<HOSTED_REGISTRY_PATH_MAX>(value_name, true) {
                Some(value_name) => value_name,
                None => return STATUS_INVALID_PARAMETER,
            };
        if key_value_information_class != KEY_VALUE_PARTIAL_INFORMATION_CLASS {
            if result_length != 0 {
                write_unaligned(result_length as *mut u32, 0);
            }
            return STATUS_NOT_SUPPORTED;
        }
        if !write_registry_arg_ascii(
            HOSTED_REGISTRY_ARG_VALUE_LEN,
            HOSTED_REGISTRY_ARG_VALUE_OFF,
            &value_name,
        ) {
            return STATUS_INVALID_PARAMETER;
        }
        let (status, value_type, data_len) =
            hosted_registry_broker_call(HOSTED_REGISTRY_OP_QUERY_HANDLE_VALUE, handle, 0, 0);
        match status {
            STATUS_SUCCESS => write_key_value_partial_raw(
                value_type as u32,
                registry_arg_data_slice(data_len as u32),
                key_value_information,
                length,
                result_length,
            ),
            status => {
                if result_length != 0 {
                    write_unaligned(result_length as *mut u32, 0);
                }
                status
            }
        }
    }
}

/// `NTSTATUS ZwSetValueKey(...)`.
extern "win64" fn s_zw_set_value_key(
    handle: u64,
    value_name: u64,
    _title_index: u32,
    typ: u32,
    data: u64,
    data_size: u32,
) -> i32 {
    unsafe {
        let Some(value_name) =
            unicode_string_to_hosted_ascii::<HOSTED_REGISTRY_PATH_MAX>(value_name, true)
        else {
            return STATUS_INVALID_PARAMETER;
        };
        if !write_registry_arg_ascii(
            HOSTED_REGISTRY_ARG_VALUE_LEN,
            HOSTED_REGISTRY_ARG_VALUE_OFF,
            &value_name,
        ) {
            return STATUS_INVALID_PARAMETER;
        }
        let status = write_registry_arg_data(data, data_size);
        if status != STATUS_SUCCESS {
            return status;
        }
        let (status, _, _) = hosted_registry_broker_call(
            HOSTED_REGISTRY_OP_SET_HANDLE_VALUE,
            handle,
            typ as u64,
            data_size as u64,
        );
        status
    }
}

