fn range_within_grant(grant_start: u64, grant_len: u64, start: u64, len: u64) -> bool {
    if grant_len == 0 || len == 0 || start < grant_start {
        return false;
    }
    let offset = start - grant_start;
    offset <= grant_len && len <= grant_len - offset
}

unsafe fn component_write_video_access_range(ptr: u64, range: VideoAccessRangeX64) {
    let mut raw = [0u8; VIDEO_ACCESS_RANGE_X64_SIZE];
    let _ = range.write(&mut raw);
    let mut i = 0usize;
    while i < raw.len() {
        write_unaligned((ptr + i as u64) as *mut u8, raw[i]);
        i += 1;
    }
}

unsafe fn component_zero_video_access_range(ptr: u64) {
    let mut i = 0usize;
    while i < VIDEO_ACCESS_RANGE_X64_SIZE {
        write_unaligned((ptr + i as u64) as *mut u8, 0);
        i += 1;
    }
}

unsafe fn component_read_video_access_range(ptr: u64) -> VideoAccessRangeX64 {
    let mut raw = [0u8; VIDEO_ACCESS_RANGE_X64_SIZE];
    let mut i = 0usize;
    while i < raw.len() {
        raw[i] = read_unaligned((ptr + i as u64) as *const u8);
        i += 1;
    }
    VideoAccessRangeX64 {
        range_start: u64::from_le_bytes([
            raw[0], raw[1], raw[2], raw[3], raw[4], raw[5], raw[6], raw[7],
        ]),
        range_length: u32::from_le_bytes([raw[8], raw[9], raw[10], raw[11]]),
        range_in_io_space: raw[12] != 0,
        range_visible: raw[13] != 0,
        range_shareable: raw[14] != 0,
        range_passive: raw[15],
    }
}

unsafe fn hosted_memory_range_granted(start: u64, len: u64) -> bool {
    let grant_start = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_MMIO_PHYS) as *const u64);
    let grant_len = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_MMIO_LEN) as *const u64);
    range_within_grant(grant_start, grant_len, start, len)
}

unsafe fn hosted_video_memory_caller_va(start: u64, len: u64) -> Option<u64> {
    let grant_start = read_volatile((FSD_SHARED_VADDR + SH_VIDEO_MEMORY_PHYS) as *const u64);
    let grant_len = read_volatile((FSD_SHARED_VADDR + SH_VIDEO_MEMORY_LEN) as *const u64);
    let caller_va = read_volatile((FSD_SHARED_VADDR + SH_VIDEO_MEMORY_CALLER_VA) as *const u64);
    if grant_start == 0
        || grant_len == 0
        || caller_va == 0
        || !hosted_memory_range_granted(start, len)
        || !range_within_grant(grant_start, grant_len, start, len)
    {
        return None;
    }
    Some(caller_va + (start - grant_start))
}

unsafe fn hosted_video_memory_64k_units() -> Option<u16> {
    let bytes = read_volatile((FSD_SHARED_VADDR + SH_VIDEO_MEMORY_LEN) as *const u64);
    let units = bytes / VIDEO_MEMORY_64K_UNIT;
    if units == 0 {
        None
    } else {
        Some(units.min(u16::MAX as u64) as u16)
    }
}

unsafe fn hosted_io_range_granted(start: u64, len: u64) -> bool {
    let grant_start = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_BASE) as *const u64);
    let grant_len = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LEN) as *const u64);
    let cap = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_CAP) as *const u64);
    cap != 0 && range_within_grant(grant_start, grant_len, start, len)
}

unsafe fn hosted_mmio_va_range_granted(start: u64, len: u64) -> bool {
    let grant_start = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_MMIO_VA) as *const u64);
    let grant_len = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_MMIO_LEN) as *const u64);
    grant_start != 0 && range_within_grant(grant_start, grant_len, start, len)
}

unsafe fn bump_shared_io_counter(offset: u64) -> u64 {
    let ptr = (FSD_SHARED_VADDR + offset) as *mut u64;
    let next = read_volatile(ptr).saturating_add(1);
    write_volatile(ptr, next);
    next
}

unsafe fn hosted_port_cap_for_component_io(port: u64, width: u64) -> Option<u64> {
    if port > u16::MAX as u64 || width == 0 || !hosted_io_range_granted(port, width) {
        return None;
    }
    let cap = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_COMPONENT_CAP) as *const u64);
    if cap == 0 { None } else { Some(cap) }
}

extern "win64" fn s_read_port_ushort(port: u64) -> u16 {
    unsafe {
        bump_shared_io_counter(SH_RESOURCE_IO_PORT_IN16_CALLS);
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_IN16_PORT) as *mut u64,
            port,
        );
        let Some(cap) = hosted_port_cap_for_component_io(port, 2) else {
            bump_shared_io_counter(SH_RESOURCE_IO_PORT_IN16_DENIED);
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_IN16_STATUS) as *mut u64,
                u64::MAX,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_IN16_VALUE) as *mut u64,
                0,
            );
            return 0;
        };
        let (value, status) = crate::io_in16_r(cap, port as u16);
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_IN16_STATUS) as *mut u64,
            status,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_IN16_VALUE) as *mut u64,
            value as u64,
        );
        if status != 0 {
            bump_shared_io_counter(SH_RESOURCE_IO_PORT_IN16_FAILURES);
            return 0;
        }
        value
    }
}

extern "win64" fn s_write_port_ushort(port: u64, value: u16) {
    unsafe {
        bump_shared_io_counter(SH_RESOURCE_IO_PORT_OUT16_CALLS);
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_OUT16_PORT) as *mut u64,
            port,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_OUT16_VALUE) as *mut u64,
            value as u64,
        );
        let Some(cap) = hosted_port_cap_for_component_io(port, 2) else {
            bump_shared_io_counter(SH_RESOURCE_IO_PORT_OUT16_DENIED);
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_OUT16_STATUS) as *mut u64,
                u64::MAX,
            );
            return;
        };
        let status = crate::io_out16(cap, port as u16, value);
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_IO_PORT_LAST_OUT16_STATUS) as *mut u64,
            status,
        );
        if status != 0 {
            bump_shared_io_counter(SH_RESOURCE_IO_PORT_OUT16_FAILURES);
        }
    }
}

extern "win64" fn s_read_port_ulong(port: u64) -> u32 {
    unsafe {
        let Some(cap) = hosted_port_cap_for_component_io(port, 4) else {
            return 0;
        };
        let (value, status) = crate::io_in32_r(cap, port as u16);
        if status == 0 { value } else { 0 }
    }
}

extern "win64" fn s_write_port_ulong(port: u64, value: u32) {
    unsafe {
        let Some(cap) = hosted_port_cap_for_component_io(port, 4) else {
            return;
        };
        if crate::io_out32(cap, port as u16, value) == 0 {
            bump_shared_io_counter(SH_RESOURCE_IO_PORT_OUT32_FAULTS);
        }
    }
}

