unsafe fn service_ndis_protocol_receive_callback(
    provider_instance: usize,
    provider_inst: DriverInstance,
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    provider_stack: [u64; PROVIDER_CALLBACK_STACK_QWORDS],
) -> Result<u64, i32> {
    let header_bytes = arg3;
    let lookahead_component = provider_stack[0];
    let lookahead_bytes = provider_stack[1];
    let packet_bytes = provider_stack[2];
    let lookahead_off = provider_marshal_align8(header_bytes).ok_or(STATUS_INVALID_PARAMETER)?;
    let used = provider_marshal_align8(
        lookahead_off
            .checked_add(lookahead_bytes)
            .ok_or(STATUS_INVALID_PARAMETER)?,
    )
    .ok_or(STATUS_INVALID_PARAMETER)?;
    if used > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let provider_header_exec = if header_bytes == 0 {
        0
    } else {
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg2, header_bytes)
            .ok_or(STATUS_INVALID_PARAMETER)?
    };
    let provider_lookahead_exec = if lookahead_bytes == 0 {
        0
    } else {
        component_to_exec_va_for_instance(
            provider_instance,
            provider_inst,
            lookahead_component,
            lookahead_bytes,
        )
        .ok_or(STATUS_INVALID_PARAMETER)?
    };

    let dependent_shared = dependent_inst.exec_shared_va;
    let dependent_base_component = FSD_SHARED_VADDR + SH_PROVIDER_EXPORT_MARSHAL_BASE;
    let dependent_base_exec = dependent_shared + SH_PROVIDER_EXPORT_MARSHAL_BASE;
    provider_marshal_zero(dependent_base_exec, used);
    let dependent_header_component = if header_bytes == 0 {
        0
    } else {
        copy_bytes(dependent_base_exec, provider_header_exec, header_bytes);
        dependent_base_component
    };
    let dependent_lookahead_component = if lookahead_bytes == 0 {
        0
    } else {
        copy_bytes(
            dependent_base_exec + lookahead_off,
            provider_lookahead_exec,
            lookahead_bytes,
        );
        dependent_base_component + lookahead_off
    };

    let mut stack_args = [0u64; PROVIDER_CALLBACK_STACK_QWORDS];
    stack_args[0] = dependent_lookahead_component;
    stack_args[1] = lookahead_bytes;
    stack_args[2] = packet_bytes;
    dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, arg1, dependent_header_component, header_bytes],
        stack_args,
    )
}

unsafe fn service_ndis_protocol_receive_complete_callback(
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
) -> Result<u64, i32> {
    dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, 0, 0, 0],
        [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
    )
}

unsafe fn service_ndis_protocol_status_callback(
    provider_instance: usize,
    provider_inst: DriverInstance,
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
) -> Result<u64, i32> {
    let used = provider_marshal_align8(arg3).ok_or(STATUS_INVALID_PARAMETER)?;
    if used > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let provider_status_exec = if arg3 == 0 {
        0
    } else {
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg2, arg3)
            .ok_or(STATUS_INVALID_PARAMETER)?
    };
    let dependent_shared = dependent_inst.exec_shared_va;
    let dependent_status_component = if arg3 == 0 {
        0
    } else {
        let dependent_exec = dependent_shared + SH_PROVIDER_EXPORT_MARSHAL_BASE;
        provider_marshal_zero(dependent_exec, used);
        copy_bytes(dependent_exec, provider_status_exec, arg3);
        FSD_SHARED_VADDR + SH_PROVIDER_EXPORT_MARSHAL_BASE
    };
    dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, arg1, dependent_status_component, arg3],
        [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
    )
}

unsafe fn service_ndis_protocol_status_complete_callback(
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
) -> Result<u64, i32> {
    dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, 0, 0, 0],
        [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
    )
}

unsafe fn service_ndis_protocol_receive_packet_callback(
    provider_instance: usize,
    provider_inst: DriverInstance,
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
    arg1: u64,
) -> Result<u64, i32> {
    let shadow = ensure_hosted_provider_ndis_packet_shadow_for_dependent_from_provider(
        provider_instance,
        provider_inst,
        record.dependent_instance,
        dependent_inst,
        arg1,
    )?;
    sync_ndis_packet_shadow_to_dependent(
        provider_instance,
        provider_inst,
        record.dependent_instance,
        dependent_inst,
        shadow,
    )?;
    let result = dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, shadow.dependent_component_va, 0, 0],
        [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
    )?;
    let Some((_index, refreshed)) =
        find_hosted_provider_ndis_packet_shadow_by_dependent(
            provider_instance,
            record.dependent_instance,
            shadow.dependent_component_va,
        )
    else {
        HOSTED_PROVIDER_NDIS_PACKET_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };
    sync_ndis_packet_shadow_to_provider(
        provider_instance,
        provider_inst,
        record.dependent_instance,
        dependent_inst,
        refreshed,
        true,
    )?;
    Ok(result)
}

pub(crate) unsafe fn service_hosted_provider_callback(
    provider_channel: &crate::spawn_hosts::PumpChannel,
    callback_cookie: u64,
    arg0: u64,
    arg1: u64,
    arg2: u64,
) -> u64 {
    HOSTED_PROVIDER_CALLBACK_REQUESTS.fetch_add(1, Ordering::Relaxed);
    let arg3 = read_volatile(
        (provider_channel.shared_va + SH_PROVIDER_EXPORT_ARG3) as *const u64,
    );
    let mut provider_stack = [0u64; PROVIDER_CALLBACK_STACK_QWORDS];
    let mut stack_index = 0usize;
    while stack_index < PROVIDER_CALLBACK_STACK_QWORDS {
        provider_stack[stack_index] = read_volatile(
            (provider_channel.shared_va + SH_PROVIDER_EXPORT_STACK_BASE + stack_index as u64 * 8)
                as *const u64,
        );
        stack_index += 1;
    }
    let Some((provider_instance, provider_inst)) = instance_by_shared_va(provider_channel.shared_va)
    else {
        return hosted_provider_callback_failure(STATUS_DEVICE_NOT_READY);
    };
    let Some(record) = hosted_provider_callback_record(callback_cookie) else {
        return hosted_provider_callback_failure(STATUS_INVALID_PARAMETER);
    };
    let Some(dependent_inst) = instance(record.dependent_instance) else {
        return hosted_provider_callback_failure(STATUS_DEVICE_NOT_READY);
    };
    if record.provider_instance != provider_instance
        || record.target == 0
        || record.callback_offset == 0
        || (record.callback_kind != HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT
            && record.callback_kind != HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL)
        || dependent_inst.fault_ep == 0
        || dependent_inst.pml4 == 0
        || dependent_inst.reply_cap == 0
        || dependent_inst.driver_object == 0
    {
        return hosted_provider_callback_failure(STATUS_INVALID_PARAMETER);
    }
    let Some(exec_code_va) =
        ExecVaWindow::try_for_instance(record.dependent_instance).map(|win| win.code_va)
    else {
        return hosted_provider_callback_failure(STATUS_DEVICE_NOT_READY);
    };
    let callback_args = [arg0, arg1, arg2, arg3];
    trace_hosted_provider_callback(b"enter", record, callback_args, &provider_stack, Ok(0));

    let dependent_shared = dependent_inst.exec_shared_va;
    let saved_dependent_irql =
        read_volatile((dependent_shared + SH_HOSTED_CURRENT_IRQL) as *const u8);
    let callback_irql = read_volatile((provider_channel.shared_va + SH_HOSTED_CURRENT_IRQL) as *const u8);
    write_volatile(
        (dependent_shared + SH_HOSTED_CURRENT_IRQL) as *mut u8,
        callback_irql,
    );

    let mut result = {
        let preflight = if record.callback_kind == HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT
            && record.callback_offset != NDIS_MINIPORT_INITIALIZE_CALLBACK_OFFSET_X64
        {
            refresh_hosted_provider_ndis_miniport_block_mirrors_for_pair(
                provider_instance,
                provider_inst,
                record.dependent_instance,
                dependent_inst,
            )
        } else {
            Ok(())
        };

        if let Err(status) = preflight {
            Err(status)
        } else {
            match record.callback_kind {
                HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT => match record.callback_offset {
                    NDIS_MINIPORT_INITIALIZE_CALLBACK_OFFSET_X64 => service_ndis_initialize_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                        arg2,
                        arg3,
                        provider_stack,
                    ),
                    NDIS_MINIPORT_QUERY_INFORMATION_CALLBACK_OFFSET_X64 => {
                        service_ndis_query_set_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                            arg3,
                            provider_stack,
                            false,
                            true,
                        )
                    }
                    NDIS_MINIPORT_SET_INFORMATION_CALLBACK_OFFSET_X64 => {
                        service_ndis_query_set_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                            arg3,
                            provider_stack,
                            true,
                            false,
                        )
                    }
                    NDIS_MINIPORT_RESET_CALLBACK_OFFSET_X64 => service_ndis_reset_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                    ),
                    NDIS_MINIPORT_ISR_CALLBACK_OFFSET_X64 => service_ndis_isr_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                        arg2,
                    ),
                    NDIS_MINIPORT_RECONFIGURE_CALLBACK_OFFSET_X64 => {
                        service_ndis_reconfigure_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                        )
                    }
                    NDIS_MINIPORT_CHECK_FOR_HANG_CALLBACK_OFFSET_X64
                    | NDIS_MINIPORT_DISABLE_INTERRUPT_CALLBACK_OFFSET_X64
                    | NDIS_MINIPORT_ENABLE_INTERRUPT_CALLBACK_OFFSET_X64
                    | NDIS_MINIPORT_HALT_CALLBACK_OFFSET_X64
                    | NDIS_MINIPORT_HANDLE_INTERRUPT_CALLBACK_OFFSET_X64 => {
                        dispatch_dependent_provider_callback(
                            record,
                            dependent_inst,
                            exec_code_va,
                            [arg0, 0, 0, 0],
                            [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
                        )
                    }
                    NDIS_MINIPORT_SEND_CALLBACK_OFFSET_X64 => service_ndis_send_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                        arg2,
                    ),
                    NDIS_MINIPORT_RETURN_PACKET_CALLBACK_OFFSET_X64 => {
                        service_ndis_return_packet_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                        )
                    }
                    NDIS_MINIPORT_SEND_PACKETS_CALLBACK_OFFSET_X64 => {
                        service_ndis_send_packets_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                        )
                    }
                    NDIS_MINIPORT_TRANSFER_DATA_CALLBACK_OFFSET_X64 => {
                        service_ndis_transfer_data_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                            arg3,
                            provider_stack,
                        )
                    }
                    _ => Err(STATUS_NOT_SUPPORTED),
                },
                HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL => match record.callback_offset {
                    NDIS_PROTOCOL_BIND_ADAPTER_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_bind_adapter_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                            arg3,
                            provider_stack,
                        )
                    }
                    NDIS_PROTOCOL_PNP_EVENT_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_pnp_event_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                        )
                    }
                    NDIS_PROTOCOL_SEND_COMPLETE_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_send_complete_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                        )
                    }
                    NDIS_PROTOCOL_TRANSFER_DATA_COMPLETE_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_transfer_data_complete_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                            arg2,
                            arg3,
                        )
                    }
                    NDIS_PROTOCOL_RECEIVE_CALLBACK_OFFSET_X64 => service_ndis_protocol_receive_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                        arg2,
                        arg3,
                        provider_stack,
                    ),
                    NDIS_PROTOCOL_RECEIVE_COMPLETE_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_receive_complete_callback(
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                        )
                    }
                    NDIS_PROTOCOL_STATUS_CALLBACK_OFFSET_X64 => service_ndis_protocol_status_callback(
                        provider_instance,
                        provider_inst,
                        record,
                        dependent_inst,
                        exec_code_va,
                        arg0,
                        arg1,
                        arg2,
                        arg3,
                    ),
                    NDIS_PROTOCOL_STATUS_COMPLETE_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_status_complete_callback(
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                        )
                    }
                    NDIS_PROTOCOL_RECEIVE_PACKET_CALLBACK_OFFSET_X64 => {
                        service_ndis_protocol_receive_packet_callback(
                            provider_instance,
                            provider_inst,
                            record,
                            dependent_inst,
                            exec_code_va,
                            arg0,
                            arg1,
                        )
                    }
                    _ => Err(STATUS_NOT_SUPPORTED),
                },
                _ => Err(STATUS_NOT_SUPPORTED),
            }
        }
    };
    write_volatile(
        (dependent_shared + SH_HOSTED_CURRENT_IRQL) as *mut u8,
        saved_dependent_irql,
    );
    if result.is_ok() {
        if let Some(dependent_inst) = instance(record.dependent_instance) {
            if let Err(status) =
                drain_hosted_work_queue_for_instance(record.dependent_instance, dependent_inst)
            {
                result = Err(status);
            }
        } else {
            result = Err(STATUS_DEVICE_NOT_READY);
        }
    }
    HOSTED_PROVIDER_CALLBACK_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
    trace_hosted_provider_callback(b"done", record, callback_args, &provider_stack, result);
    match result {
        Ok(value) => value,
        Err(status) => hosted_provider_callback_failure(status),
    }
}

unsafe fn add_provider_domain_if_callable(
    provider: HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
    provider_domains: &mut Vec<PlannedProviderDomain>,
) -> Option<bool> {
    if provider_domain_plan_contains(provider_domains, &provider) {
        return Some(true);
    }
    let Some((_singleton_index, singleton)) = find_hosted_provider_singleton(&provider) else {
        return Some(false);
    };
    if singleton.image_frames == 0 || singleton.image_frames > FSD_IMAGE_MAX_FRAMES {
        print_str(b"[driver-launch] registered provider image frame count invalid ");
        print_str(provider.as_bytes());
        print_str(b"\n");
        return None;
    }
    match classify_hosted_provider_domain(Some(hosted_provider_domain_descriptor(
        singleton,
    ))) {
        Ok(HostedProviderDomainStatus::Callable(_binding)) => {}
        Ok(HostedProviderDomainStatus::Absent | HostedProviderDomainStatus::MetadataOnly) => {
            return Some(false)
        }
        Err(error) => {
            print_str(b"[driver-launch] registered provider domain invalid ");
            print_str(provider.as_bytes());
            print_str(b" reason=");
            print_hosted_provider_domain_error(error);
            print_str(b"\n");
            return None;
        }
    }
    provider_domains.try_reserve_exact(1).ok()?;
    provider_domains.push(PlannedProviderDomain { provider });
    HOSTED_PROVIDER_DOMAIN_BINDINGS.fetch_add(1, Ordering::Relaxed);
    Some(true)
}

fn hosted_dependency_provider_matches(dep: LoadedDependencyImage, provider: &str) -> bool {
    dep.present && hosted_ascii_eq_ignore_case_str(&dep.provider, provider)
}

unsafe fn register_loaded_dependency_image(
    provider: &str,
    exec_va: u64,
    run_va: u64,
    image_len: u32,
) -> Option<()> {
    let mut provider_name = HostedAscii::<HOSTED_DEP_PROVIDER_MAX>::empty();
    if !provider_name.set_str(provider) {
        return None;
    }
    let images = hosted_dependency_images_mut();
    if let Some(slot) = images
        .iter_mut()
        .find(|slot| hosted_dependency_provider_matches(**slot, provider))
    {
        *slot = LoadedDependencyImage {
            present: true,
            provider: provider_name,
            exec_va,
            run_va,
            image_len,
        };
        return Some(());
    }
    images.try_reserve_exact(1).ok()?;
    images.push(LoadedDependencyImage {
        present: true,
        provider: provider_name,
        exec_va,
        run_va,
        image_len,
    });
    Some(())
}

